#!/usr/bin/env node
//
// Cross-checks the Merkle root against viem (S7, invariant A4).
//
//   node scripts/verify-merkle-viem.mjs
//
// # Why a third implementation
//
// The corpus in testdata/merkle-vectors.json is generated by Go and consumed by both Go
// and Solidity. Those two are checked against each other in CI. viem is a third,
// independently written implementation with no shared code, so agreeing with it is
// evidence that the construction is a faithful reading of the specification rather than a
// convention two of our own files happen to share.
//
// It was originally a one-off manual check, which is worth little: a check nobody re-runs
// cannot catch a regression. Running it in CI is what turns it into a gate.
//
// # What it does NOT need
//
// No network, no chain, no deployment. It recomputes a hash tree in JavaScript and compares
// it to committed numbers.
//
// Exits non-zero and prints the differing tree on any mismatch.

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { keccak256, concatHex } from "viem";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..");
const corpusPath = join(repoRoot, "testdata", "merkle-vectors.json");

// Domain separation, matching internal/merkle and RelayAnchor.sol.
const LEAF_PREFIX = "0x00";
const NODE_PREFIX = "0x01";
const ZERO_ID = "0x" + "00".repeat(32);

// leaf(id) = keccak256(0x00 || id)
const leafHash = (id) => keccak256(concatHex([LEAF_PREFIX, id]));

// node(left, right) = keccak256(0x01 || left || right)
const nodeHash = (left, right) => keccak256(concatHex([NODE_PREFIX, left, right]));

// nextPow2 mirrors the Go padding width.
function nextPow2(n) {
  if (n <= 1) return 1;
  let p = 1;
  while (p < n) p <<= 1;
  return p;
}

// root mirrors internal/merkle.Root: leaf hashes, pad to a power of two, then fold.
function root(leaves) {
  if (leaves.length === 0) return keccak256("0x");
  if (leaves.length === 1) return leafHash(leaves[0]);

  const width = nextPow2(leaves.length);
  let level = leaves.map(leafHash);
  while (level.length < width) level.push(leafHash(ZERO_ID));

  while (level.length > 1) {
    const next = [];
    for (let i = 0; i < level.length; i += 2) next.push(nodeHash(level[i], level[i + 1]));
    level = next;
  }
  return level[0];
}

// foldProof mirrors RelayAnchor.foldProof, so the proofs are checked too rather than only
// the roots. A root that agreed while proofs did not would mean the two implementations
// diverged on child ordering.
function foldProof(leaf, index, siblings) {
  let h = leafHash(leaf);
  let pos = index;
  for (const sibling of siblings) {
    h = pos % 2 === 0 ? nodeHash(h, sibling) : nodeHash(sibling, h);
    pos = Math.floor(pos / 2);
  }
  return h;
}

function main() {
  let corpus;
  try {
    corpus = JSON.parse(readFileSync(corpusPath, "utf8"));
  } catch (err) {
    console.error(`verify-merkle-viem: cannot read ${corpusPath}: ${err.message}`);
    console.error("  regenerate it with: go run internal/devtools/gen_merkle_vectors.go");
    process.exit(1);
  }

  // A sanity check on viem itself before trusting it to judge anything: the empty string's
  // keccak256 is a well-known constant, and if this fails the comparison below is
  // meaningless.
  const EMPTY = "0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470";
  if (keccak256("0x") !== EMPTY) {
    console.error("verify-merkle-viem: viem's keccak256 disagrees with the known empty-string hash");
    process.exit(1);
  }
  if (corpus.emptyRoot !== EMPTY) {
    console.error(`verify-merkle-viem: corpus emptyRoot ${corpus.emptyRoot} != ${EMPTY}`);
    process.exit(1);
  }

  if (!Array.isArray(corpus.trees) || corpus.trees.length === 0) {
    console.error("verify-merkle-viem: the corpus holds no trees");
    process.exit(1);
  }

  let rootsChecked = 0;
  let proofsChecked = 0;
  const failures = [];

  for (const tree of corpus.trees) {
    const computed = root(tree.leaves);
    rootsChecked++;
    if (computed !== tree.root) {
      failures.push(`tree ${tree.name}: viem root ${computed} != corpus ${tree.root}`);
      continue;
    }

    for (const proof of tree.proofs) {
      proofsChecked++;
      const folded = foldProof(proof.leaf, proof.index, proof.siblings);
      if (folded !== tree.root) {
        failures.push(`tree ${tree.name} index ${proof.index}: viem proof folds to ${folded}, want ${tree.root}`);
      }
    }
  }

  if (failures.length > 0) {
    console.error("verify-merkle-viem: FAIL");
    for (const f of failures) console.error(`  ${f}`);
    console.error(
      "\n  A mismatch means Go, Solidity and viem do not agree on the Merkle construction.\n" +
        "  Do not weaken the check: an on-chain proof would be unverifiable against whichever\n" +
        "  side differs.",
    );
    process.exit(1);
  }

  console.log(
    `verify-merkle-viem: PASS (${rootsChecked} roots, ${proofsChecked} proofs agree across Go, Solidity and viem)`,
  );
}

main();
